  self::assertTrue(method_exists($resolver,'heldPackage'),'Current approved held-package join required.');$held=PrintifyApiApprovalFixture::checked($resolver::heldPackage($s,1,$id,$spec,$pkg['package']));self::assertSame($pkg['package'],$held['package_hash']);self::assertFalse($held['business_package_binding_approved']);self::assertFalse($held['external_execution_authorized']);self::assertFalse($held['held_export']['etsy_draft']['publishing_authorized']);self::assertSame($r['evidence_hash'],$held['business_artwork_evidence_hash']);self::assertWPError($resolver::heldPackage($s,1,$id,$spec,str_repeat('f',64)));
  global $wpdb;foreach(['wrong_hash','wrong_supplier','wrong_product','wrong_dpi','unapproved','unlinked','stale','revoked'] as $mode){$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::asset_specs().' WHERE id=%d',$spec),ARRAY_A);$link=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::production_plan_assets().' WHERE asset_spec_id=%d',$spec),ARRAY_A);$changed=$binding;if($mode==='wrong_hash')$changed['artwork_version_hash']=str_repeat('f',64);if($mode==='wrong_supplier')$changed['supplier_workflow_hash']=str_repeat('f',64);$data=['content_requirements'=>wp_json_encode(['native_artwork_binding'=>$changed])];if($mode==='wrong_product')$data['product_version_id']=$version+100000;if($mode==='wrong_dpi')$data['dpi']=72;if($mode==='unapproved')$data['state']='DRAFT';$wpdb->update(Tables::asset_specs(),$data,['id'=>$spec],array_fill(0,count($data),'%s'),['%d']);if($mode==='unlinked')$wpdb->delete(Tables::production_plan_assets(),['asset_spec_id'=>$spec],['%d']);if($mode==='revoked')WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());try{self::assertWPError($resolver::resolve($s,1,$id,$spec,$mode==='stale'?str_repeat('f',64):null),$mode);}finally{$wpdb->update(Tables::asset_specs(),$row,['id'=>$spec],array_fill(0,count($row),'%s'),['%d']);if($mode==='unlinked')$wpdb->insert(Tables::production_plan_assets(),$link,array_fill(0,count($link),'%s'));}}
 }

