 public function testInvalidOrUnavailableBusinessEvidenceDenies(string $mode):void {
  self::assertTrue(class_exists(NativeBusinessEvidence::class));[$s,$id,$v,$owner]=$this->product();global $wpdb;
  if($mode==='version')$wpdb->update(Tables::product_versions(),['state'=>'REVIEW'],['id'=>$v],['%s'],['%d']);elseif($mode==='owner')$wpdb->update(Tables::pod_business_mappings(),['store_id'=>2147483647],['id'=>$owner],['%d'],['%d']);elseif($mode==='mapping')$wpdb->update(Tables::pod_mappings(),['state'=>'SUPERSEDED'],['id'=>$id],['%s'],['%d']);elseif($mode==='foreign_shop')$s=new ShopBinding(3,'standard_pod',$s->integrationId,$s->providerShopId,$s->environment,$s->revision,$s->credential,$s->bindingHash,$s->expiresAt);elseif($mode==='revoked')WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());elseif($mode==='outer_transaction')$wpdb->query('START TRANSACTION');elseif($mode==='ambiguous'){$copy=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_business_mappings().' WHERE id=%d',$owner),ARRAY_A);unset($copy['id']);$copy['product_version_id']=$v+214748;$copy['idempotency_key']=null;self::assertSame(1,$wpdb->insert(Tables::pod_business_mappings(),$copy,array_fill(0,count($copy),'%s')));}
  if(in_array($mode,['approval_actor','plan_approval_actor'],true)){$map=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_mappings().' WHERE id=%d',$id),ARRAY_A);$type=$mode==='approval_actor'?'mapping':'plan';$event=$mode==='approval_actor'?'pod_state_changed':'production_state_changed';$target=$mode==='approval_actor'?$id:(int)$map['production_plan_id'];self::assertSame(3,$wpdb->update(Tables::audit_log(),['actor_id'=>$this->fixture->reviewer],['object_type'=>$type,'event_type'=>$event,'object_id'=>(string)$target],['%d'],['%s','%s','%s']));}
  if($mode==='temporary_audit'){$table=Tables::audit_log();$rows=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);$ddl=$wpdb->get_row('SHOW CREATE TABLE '.$table,ARRAY_N);self::assertNotFalse($wpdb->query(preg_replace('/^CREATE TABLE/','CREATE TEMPORARY TABLE',$ddl[1])));foreach($rows as $row)self::assertSame(1,$wpdb->insert($table,$row,array_fill(0,count($row),'%s')));}
  if($mode==='overflow')self::assertSame(1,$wpdb->update(Tables::pod_mappings(),['product_version_id'=>'18446744073709551615'],['id'=>$id],['%s'],['%d']));if($mode==='approval_missing')$wpdb->delete(Tables::audit_log(),['event_type'=>'product_version_state_changed','object_id'=>(string)$v],['%s','%s']);if($mode==='temporary_shadow'){$ddl=$wpdb->get_row('SHOW CREATE TABLE '.Tables::pod_mappings(),ARRAY_N);self::assertNotFalse($wpdb->query(preg_replace('/^CREATE TABLE/','CREATE TEMPORARY TABLE',$ddl[1])));$shadow=$wpdb->get_row('SHOW CREATE TABLE '.Tables::pod_mappings(),ARRAY_N);self::assertStringContainsString('CREATE TEMPORARY TABLE',$shadow[1]);}$filter=static fn(string $q):string=>str_contains($q,'FROM '.Tables::pod_mappings().' WHERE')?'SELECT * FROM missing_native_business_evidence':$q;if(in_array($mode,['missing_storage','rollback_unknown'],true))add_filter('query',$filter);$changed=false;$boundary=static function(string $q)use($mode,&$changed,$wpdb,$v):string{if($mode==='rollback_unknown'&&$q==='ROLLBACK')return 'SELECT * FROM missing_rollback_confirmation';if($q==='COMMIT'&&!$changed){$changed=true;if($mode==='commit_unknown')return 'SELECT * FROM missing_business_commit_confirmation';if($mode==='revoked_at_commit'){$wpdb->query('COMMIT');WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());}if($mode==='changed_at_commit'){$wpdb->query('COMMIT');$wpdb->update(Tables::product_versions(),['notes'=>'concurrent change'],['id'=>$v],['%s'],['%d']);}}return $q;};if(in_array($mode,['commit_unknown','changed_at_commit','rollback_unknown','revoked_at_commit'],true))add_filter('query',$boundary);
  try{$denied=NativeBusinessEvidence::product($s,1,$id);self::assertWPError($denied);if($mode==='rollback_unknown')self::assertSame('printify_native_business_cleanup_unknown',$denied->get_error_code());if($mode==='outer_transaction')self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertTrue(DigiForge\Core\Settings::safety_locked());}finally{if(in_array($mode,['missing_storage','rollback_unknown'],true))remove_filter('query',$filter);if(in_array($mode,['commit_unknown','changed_at_commit','rollback_unknown','revoked_at_commit'],true)){remove_filter('query',$boundary);if($mode!=='rollback_unknown')self::assertTrue($changed);}if($mode==='temporary_shadow')$wpdb->query('DROP TEMPORARY TABLE '.Tables::pod_mappings());if($mode==='temporary_audit')$wpdb->query('DROP TEMPORARY TABLE '.Tables::audit_log());}
 }
